// Learn mode script for CPR/First Aid lab 01.
// Each step names the rescuer, the tool to use, the scene object to click,
// the action event that completes it, and what to teach.
// ok(ev) returns true, or a correction (the student redoes the step).
// need lists phrases the narration should include (a miss is a tip, not a redo).
import {PATTERNS as RX, reportScore} from './mock-lab-cpr.js';

const rateOk = e => e.d.rate >= 98 && e.d.rate <= 122;
const compressOk = e => {
  if (!rateOk(e)) return `Your rate was ${Math.round(e.d.rate)}/min. Aim for 100–120 (about 2 taps per second). Tap 30 again.`;
  if (e.d.depth < 2 || e.d.depth > 2.4) return `Depth was ${e.d.depth.toFixed(1)} in. Set the slider between 2.0 and 2.4 in, then tap 30 again.`;
  if (e.d.recoil !== 'full') return 'Choose “Let the chest recoil fully”, then tap 30 again.';
  return true;
};
const breathsOk = e => (e.d.holds || []).slice(0, 2).every(h => h >= .6 && h <= 1.7) ? true : 'Each breath should be held for about 1 second (0.6–1.7 s). Try the 2 breaths again.';
const ecOk = e => e.d.steps.every(Boolean) ? true : 'One of the E-C clamp choices was wrong. Look for the ★ coach picks and seal again.';
const ecReset = (S, ev) => { S.r[ev.r].sealed = false; if (S.panel?.id === 'ecClamp') S.panel.sealed = false; };

